public static String substituteVariables(String str, Properties props) {
  Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
  Matcher matcher = pattern.matcher(str);
  StringBuffer sb = new StringBuffer();
  while (matcher.find()) {
    String varName = matcher.group(1);
    String varValue = props.getProperty(varName);
    if (varValue == null) {
      throw new IllegalArgumentException("Variable not found: " + varName);
    }
    matcher.appendReplacement(sb, varValue);
  }
  matcher.appendTail(sb);
  return sb.toString();
}

